// Detect any edge of the 8-bit input signal. The output is a stage-delayed
// version of the input, i.e. the output is 1 the cycle after the input signal
// changes from 0 to 1 or from 1 to 0.
module TopModule(
    input clk,
    input [7:0] in,
    output reg [7:0] anyedge
);
    reg [7:0] in_d1;
    wire [7:0] edge;
    always @(posedge clk) begin
        in_d1 <= in;
        anyedge <= edge;
    end
    genvar i;
    for (i = 0; i < 8; i = i + 1) begin
        LATCH_EDGE_D1 #(.INIT(1)) edge0 (
            .clk(clk), .rst(1'b0), .in(in[i]), .in_d1(in_d1[i]), .out(edge[i])
        );
    end
endmodule

