module TopModule(input clk, input [7:0] in, output [7:0] anyedge);
  reg [7:0] prev;
  wire [7:0] changed;
  // Detect when any bit changes from the previous value.
  assign changed = (in ^ prev);
  // Register the previous value.
  always @(posedge clk) prev <= in;
  // Set the output to 1 in the same cycle as the transition.
  assign anyedge = changed & ~(changed & (changed - 1));
endmodule

